// THINGMON rules — the pure game maths behind the Thingmon app suite
// (schemas/appSuites/thingmon.ts): eight elemental types and their chart,
// the move library, level-scaled stats, the damage / catch / flee formulas,
// experience and evolution. Everything is deterministic given the injected
// unit-interval generator, JSON-safe, and bounded (a battle turn touches two
// creatures and returns a handful of log lines).
//
// The species catalogue itself (60 original creatures + their pixel art) is
// generated by scripts/generate-thingmon-sprites.mjs into data/species.ts.

import { THINGMON_SPECIES_DATA } from './data/species';

export type ThingmonType = 'ember' | 'tide' | 'bloom' | 'spark' | 'frost' | 'stone' | 'shade' | 'glow';
export type Rarity = 'common' | 'uncommon' | 'rare' | 'legendary';
export type Rng = () => number;

export type Species = {
	id: number;
	slug: string;
	name: string;
	line: string;
	archetype: string;
	stage: number;
	types: ThingmonType[];
	rarity: Rarity;
	evolvesTo: { id: number; level: number } | null;
	evolvesFrom: number | null;
	habitats: string[];
	genus: string;
	flavor: string;
	baseStats: { hp: number; atk: number; def: number; spd: number };
	catchRate: number;
	baseExp: number;
	heightM: number;
	weightKg: number;
	sprite: string;
};

export const SPECIES: Species[] = (THINGMON_SPECIES_DATA as unknown as Species[]).map((entry) => ({ ...entry, types: [...entry.types] as ThingmonType[], habitats: [...entry.habitats] }));
const BY_ID = new Map(SPECIES.map((entry) => [entry.id, entry]));
const BY_SLUG = new Map(SPECIES.map((entry) => [entry.slug, entry]));
export const SPECIES_COUNT = SPECIES.length;

export const speciesById = (id: number): Species | undefined => BY_ID.get(id);
export const speciesBySlug = (slug: string): Species | undefined => BY_SLUG.get(slug.toLowerCase());
export const getSpecies = (idOrSlug: unknown): Species => {
	const found = typeof idOrSlug === 'number' ? speciesById(idOrSlug) : typeof idOrSlug === 'string' ? speciesBySlug(idOrSlug.trim()) || speciesById(Number(idOrSlug)) : undefined;
	if (!found) throw new Error(`No Thingmon species matches ${String(idOrSlug).slice(0, 40)}`);
	return found;
};

// ── types ───────────────────────────────────────────────────────────────────
