	tide: { emoji: '🌊', color: '#3f8fe0', ink: '#ffffff', strong: ['ember', 'stone'], resist: ['bloom', 'spark'] },
	bloom: { emoji: '🌿', color: '#5fb85a', ink: '#ffffff', strong: ['tide', 'stone'], resist: ['ember', 'frost'] },
	spark: { emoji: '⚡', color: '#f4c430', ink: '#3a2d00', strong: ['tide', 'glow'], resist: ['stone', 'shade'] },
	frost: { emoji: '❄️', color: '#9fd8f5', ink: '#1d3f5a', strong: ['bloom', 'spark'], resist: ['ember', 'stone'] },
	stone: { emoji: '🪨', color: '#9a8f82', ink: '#ffffff', strong: ['ember', 'frost', 'spark'], resist: ['tide', 'bloom'] },
